from build_magazine import page,write,E
import json
from pathlib import Path
D=json.loads((Path(__file__).resolve().parent.parent/'data/events.json').read_text())
# Accessible source links remain usable if JavaScript is unavailable.
fallback='<noscript><section class="wrap"><h2>Organizer-checked listings</h2><p>JavaScript is needed for date filtering and automatic expiry. Check each organizer’s current date and availability.</p><ul>'+''.join('<li><a href="'+E(e['sourceUrl'])+'">'+E(e['title'])+' · '+E(e['start'][:10])+' · '+E(e['venue'])+'</a></li>' for e in D['events'])+'</ul></section></noscript>'
body='''<section class="library-heading wrap"><p class="eyebrow">New England · selected sensory-friendly events</p><h1>The calendar.</h1><p class="article-dek">Something good on the horizon.</p><p class="quiet-copy">Organizer-checked listings, with the actual access details close at hand. “Sensory-friendly” means different things in different places. Check the age range, supports and booking requirements before making a plan.</p></section><section class="wrap event-workspace" data-events><form class="event-filters" role="search"><label>Where?<select name="state"><option value="">All New England</option><option value="CT">Connecticut</option><option value="ME">Maine</option><option value="MA">Massachusetts</option><option value="NH">New Hampshire</option><option value="RI">Rhode Island</option><option value="VT">Vermont</option></select></label><label>From<input name="from" type="date"></label><label>Search<input name="q" type="search" placeholder="Museum, storytime, Halloween…"></label><button type="reset" class="reset-link">Clear filters</button></form><p class="event-summary" role="status" aria-live="polite">Loading upcoming listings…</p><div class="event-list"></div><div class="event-empty empty-state" hidden><h2>No dated listings in this view.</h2><p>Try another date or state. The organizer directory below may still have a useful program.</p></div><div class="event-error callout" hidden><h2>The event list could not load.</h2><p>You can still check the official organizer pages below. Please try this page again later.</p></div><aside class="calendar-note"><h2>What this calendar can promise.</h2><p>Past events disappear automatically in your browser. New events are reviewed before they appear. A scheduled source-checking system is prepared; its first live run has not been verified. This is a selected calendar, not every event in New England.</p><p data-refresh-note>Listing details were checked against organizer sources on October 3, 2026. A recent file update does not mean an organizer has reconfirmed an event.</p><p>Times are shown in New England local time (America/New_York), including daylight saving changes. Confirm dates, availability and access arrangements directly before traveling.</p></aside><section class="organizer-directory"><p class="eyebrow">Straight to the source</p><h2>Keep these organizers in reach.</h2><div class="organizer-grid">'''+''.join(f'<a href="{E(s["url"])}"><strong>{E(s["name"])}</strong><span>{E(s.get("state","New England"))} · Official program information ↗</span></a>' for s in D['sources'])+'''</div></section></section>'''+fallback
write('calendar.html',page('Sensory-friendly New England events','Organizer-checked sensory-friendly New England event listings with dates, ages, access details and booking links.','/calendar.html',body,'calendar-page','<script src="/assets/events.js?v=magazine-20261003" defer></script>'))
